package com.keepcalm.placementportal.service;import com.keepcalm.placementportal.entity.*;import com.keepcalm.placementportal.exception.DomainException;import com.keepcalm.placementportal.repository.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service @RequiredArgsConstructor public class StudentEventService{private final StudentRepository students;private final RoundParticipantRepository participants;private final CurrentUserService current;@Transactional(readOnly=true)public List<Map<String,Object>> events(){Student s=students.findByUserId(current.principal().userId()).orElseThrow(()->DomainException.notFound("Student not found"));return participants.findByApplicationStudentId(s.getId()).stream().filter(p->!p.getRound().isArchived()).map(p->Map.<String,Object>of("id",p.getRound().getId(),"type","SELECTION_ROUND","title",p.getRound().getName(),"driveId",p.getRound().getDrive().getId(),"startsAt",p.getRound().getStartsAt(),"endsAt",p.getRound().getEndsAt(),"location",Objects.toString(p.getRound().getLocation(),""),"attendanceStatus",p.getAttendanceStatus().name())).toList();}public List<Map<String,Object>> calendar(){return events();}}
